update country_flag_history set image_url = '/flags/history/es-0000.svg' where id = 2136 and iso_code = 'es';
update country_flag_history set label_fr = 'Monarchie des Bourbons (1701-1760)', label_en = 'Bourbon monarchy (1701–1760)', notes_fr = 'Avec Philippe V, premier roi Bourbon, le drapeau blanc de la maison de Bourbon porte les armes royales d''Espagne.', notes_en = 'Under Philip V, the first Bourbon king, the white flag of the House of Bourbon carried the royal arms of Spain.' where id = 2354 and iso_code = 'es';
update country_flag_history set label_fr = 'Monarchie des Bourbons (1760-1843)', label_en = 'Bourbon monarchy (1760–1843)', notes_fr = 'Sous Charles III, les armes royales sont redessinées. En 1785, il crée pour la marine le pavillon rouge et jaune, plus visible en mer, qui deviendra le drapeau national en 1843.', notes_en = 'Under Charles III the royal arms were redrawn. In 1785 he created the red and yellow naval ensign, easier to see at sea, which would become the national flag in 1843.' where id = 2355 and iso_code = 'es';
update country_flag_history set label_fr = 'Royaume d''Espagne (rouge et jaune, 1843-1873)', label_en = 'Kingdom of Spain (red and yellow, 1843–1873)', notes_fr = 'Le 13 octobre 1843, Isabelle II étend le pavillon rouge et jaune de la marine à l''armée de terre : il devient le drapeau de toute l''Espagne.', notes_en = 'On 13 October 1843 Isabella II extended the navy''s red and yellow ensign to the army: it became the flag of all Spain.' where id = 2356 and iso_code = 'es';
update country_flag_history set date_start = '1938-02-02', label_fr = 'État espagnol (aigle de saint Jean, 1938-1945)', label_en = 'Spanish State (Eagle of Saint John, 1938–1945)', notes_fr = 'Le régime franquiste place sur le rouge et jaune l''aigle de saint Jean, emprunté aux Rois catholiques, avec la devise « Una, Grande y Libre ».', notes_en = 'Franco''s regime placed on the red and yellow the Eagle of Saint John, borrowed from the Catholic Monarchs, with the motto "Una, Grande y Libre".' where id = 2357 and iso_code = 'es';
update country_flag_history set label_fr = 'État espagnol (1945-1977)', label_en = 'Spanish State (1945–1977)', notes_fr = 'Le décret du 11 octobre 1945 redessine les armoiries à l''aigle, en usage jusqu''à la Transition démocratique.', notes_en = 'The decree of 11 October 1945 redrew the eagle arms, which stayed in use until the democratic Transition.' where id = 2358 and iso_code = 'es';
update country_flag_history set label_fr = 'Transition démocratique (1977-1981)', label_en = 'Democratic Transition (1977–1981)', notes_fr = 'Pendant la Transition, l''aigle est conservé mais redessiné, la devise passant au-dessus de sa tête ; il est remplacé fin 1981 par les armoiries actuelles.', notes_en = 'During the Transition the eagle was kept but redrawn, with the motto moved above its head; it was replaced by the current arms at the end of 1981.' where id = 2359 and iso_code = 'es';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('es', '/flags/history/es-1873.svg', '1873-02-11', '1874-12-29', 'Première République', 'First Spanish Republic', 'La Première République garde le rouge et jaune mais retire la couronne royale des armoiries.', 'The First Republic kept the red and yellow but removed the royal crown from the arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('es', '/flags/history/es-1874.svg', '1874-12-29', '1931-04-14', 'Restauration (1874-1931)', 'Restoration (1874–1931)', 'Avec la Restauration d''Alphonse XII, la couronne revient sur les armes ; ce drapeau flotte jusqu''à la proclamation de la Seconde République.', 'With Alfonso XII''s Restoration the crown returned to the arms; this flag flew until the Second Republic was proclaimed.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('es', '/flags/history/es-1936.svg', '1936-08-29', '1938-02-02', 'Camp nationaliste (1936-1938)', 'Nationalist faction (1936–1938)', 'Pendant la guerre civile, le camp nationaliste rétablit dès l''été 1936 le rouge et jaune, d''abord avec des armoiries sans couronne.', 'During the Civil War the Nationalists brought back the red and yellow in summer 1936, at first with arms lacking a crown.');
